# Lanternhold v133: Discord Activity sign-in, server part. Paste into AWS CloudShell (us-east-1). Needs John's go.
# Creates Lambda lanternhold-discordlogin (from infra/lambda/discordlogin.js) with two routes:
#   POST /discord/login (no sign-in: swaps the Activity's Discord code, signs the player in)
#   POST /discord/link  (with the game's sign-in: links a Discord account to the signed-in hero)
# It reuses the role of lanternhold-wixlogin (trade table Get/Put + the Cognito calls), and copies its TABLE/POOL/CLIENT settings.
# It asks for the Discord app's client secret (Developer Portal > Lanternhold > OAuth2 > Client Secret; Reset Secret if it is hidden).
# The secret goes only into the Lambda's settings. Touches no existing Lambda or route. Safe to run twice.
set -e
R=us-east-1; API=nyu3u8gc73; ACC=$(aws sts get-caller-identity --query Account --output text); F=lanternhold-discordlogin
read -rsp "Paste the Discord client secret, then press Enter: " DC_SECRET; echo
[ ${#DC_SECRET} -ge 20 ] || { echo "That does not look like a client secret. Nothing changed."; exit 1; }
mkdir -p ~/lhv133/dc && cd ~/lhv133
# 1. code
echo  | base64 -d > dc/index.js
(cd dc && zip -qj ../dc.zip index.js)
# 2. settings from the Born 2 Game sign-in function
ROLE=$(aws lambda get-function-configuration --function-name lanternhold-wixlogin --query Role --output text)
TABLE=$(aws lambda get-function-configuration --function-name lanternhold-wixlogin --query Environment.Variables.TABLE --output text)
POOL=$(aws lambda get-function-configuration --function-name lanternhold-wixlogin --query Environment.Variables.POOL --output text)
CLIENT=$(aws lambda get-function-configuration --function-name lanternhold-wixlogin --query Environment.Variables.CLIENT --output text)
ENVV="Variables={TABLE=$TABLE,POOL=$POOL,CLIENT=$CLIENT,DC_ID=1575635134277886114,DC_SECRET=$DC_SECRET}"
# 3. the Lambda
if aws lambda get-function --function-name $F >/dev/null 2>&1; then
  aws lambda update-function-code --function-name $F --zip-file fileb://dc.zip >/dev/null
  aws lambda wait function-updated --function-name $F
  aws lambda update-function-configuration --function-name $F --environment "$ENVV" >/dev/null
else
  aws lambda create-function --function-name $F --runtime nodejs22.x --handler index.handler --memory-size 256 --timeout 25 \
    --role "$ROLE" --environment "$ENVV" --zip-file fileb://dc.zip >/dev/null
fi
aws lambda wait function-updated --function-name $F
# 4. routes: login without sign-in (like POST /store/login), link with the same sign-in check as GET /boss
AUTH=$(aws apigatewayv2 get-routes --api-id $API --query "Items[?RouteKey=='GET /boss'].AuthorizerId" --output text)
ARN=arn:aws:lambda:$R:$ACC:function:$F
INT=$(aws apigatewayv2 get-integrations --api-id $API --query "Items[?IntegrationUri=='$ARN'].IntegrationId" --output text)
[ -z "$INT" ] && INT=$(aws apigatewayv2 create-integration --api-id $API --integration-type AWS_PROXY --integration-uri $ARN --payload-format-version 2.0 --query IntegrationId --output text)
aws lambda add-permission --function-name $F --statement-id apigw-discord --action lambda:InvokeFunction --principal apigateway.amazonaws.com \
  --source-arn "arn:aws:execute-api:$R:$ACC:$API/*/*/*" >/dev/null 2>&1 || true
[ -z "$(aws apigatewayv2 get-routes --api-id $API --query "Items[?RouteKey=='POST /discord/login'].RouteId" --output text)" ] && \
  aws apigatewayv2 create-route --api-id $API --route-key "POST /discord/login" --target "integrations/$INT" >/dev/null
[ -z "$(aws apigatewayv2 get-routes --api-id $API --query "Items[?RouteKey=='POST /discord/link'].RouteId" --output text)" ] && \
  aws apigatewayv2 create-route --api-id $API --route-key "POST /discord/link" --authorization-type JWT --authorizer-id "$AUTH" --target "integrations/$INT" >/dev/null
# 5. smoke tests: login with a fake code must say 401, link without sign-in must say 401
curl -s -o /dev/null -w "login %{http_code}\n" -X POST -H 'content-type: application/json' -d '{"code":"not-a-real-code"}' "https://$API.execute-api.$R.amazonaws.com/discord/login"
curl -s -o /dev/null -w "link %{http_code}\n" -X POST "https://$API.execute-api.$R.amazonaws.com/discord/link"
echo "done. Undo: delete routes POST /discord/login and POST /discord/link, their integration, and Lambda $F."
